/// Researched steering facts for `provider`.
pub(crate) fn provider_steering(provider: Provider) -> &'static ProviderSteering {
    match provider {
        Provider::Claude => &CLAUDE_STEERING,
        Provider::Codex => &CODEX_STEERING,
        Provider::Gemini => &GEMINI_STEERING,
        Provider::Goose => &GOOSE_STEERING,
        Provider::KimiCode => &KIMI_STEERING,
        Provider::OpenCode => &OPENCODE_STEERING,
        Provider::QwenCode => &QWEN_STEERING,
        Provider::Kilo => &KILO_STEERING,
        Provider::Pi => &PI_STEERING,
        Provider::Antigravity => &ANTIGRAVITY_STEERING,
    }
}

